class Registry:
    def __init__(self):
        self._plugins = {}

    def register(self, name, fn):
        if name in self._plugins:
            raise ValueError(f"Plugin '{name}' is already registered")
        self._plugins[name] = fn

    def get(self, name):
        return self._plugins[name]

